INSERT INTO qna_entries (question, answer, category, approved, source_ref)
SELECT x.question, x.answer, x.category, true, 'glovek_qna'
FROM jsonb_to_recordset('[{"category":"서비스 개요","question":"Glovek 틱톡샵 멀티몰 서비스(T Partners)란 정확히 무엇인가요?","answer":"Glovek이 운영하는 틱톡샵 공식 멀티몰(@Glovek)에 브랜드 제품을 입점시키고, 현지화 운영·인플루언서 마케팅·물류·정산까지 일괄 대행하는 월 구독형 글로벌 셀프 입점 서비스입니다. 브랜드는 별도 법인 설립 없이 미국·베트남·태국·말레이시아·싱가포르 5개국에 동시 진출할 수 있습니다."},{"category":"서비스 개요","question":"서비스 신청부터 실제 판매 시작까지 얼마나 걸리나요?","answer":"인증 준비가 완료된 경우 최소 7일, 최대 30일이 소요됩니다. 신청 접수(1일 이내) → 1:1 온보딩 미팅(3영업일 이내 일정 확정) → 등급 진단 및 전략 수립(3~5일) → 상세페이지 번역·스토어 세팅(7~10일) → 시딩 및 런칭(3~5일) 순서로 진행되며, 국가별 인증 준비 상황에 따라 기간이 달라질 수 있습니다."},{"category":"서비스 개요","question":"기존에 틱톡 계정이 없어도 입점이 가능한가요?","answer":"네, 가능합니다. Glovek의 틱톡샵 공식 계정(@Glovek)을 통해 입점하므로 브랜드가 별도 틱톡 계정을 보유하지 않아도 즉시 판매를 시작할 수 있습니다. 단, Onboarding Track 이용 시에는 브랜드 자체 채널 개설 및 온보딩을 지원합니다."},{"category":"서비스 개요","question":"한 번에 최대 몇 개 국가에 동시 진출할 수 있나요?","answer":"최대 5개국(미국·베트남·태국·말레이시아·싱가포르)에 동시 진출 가능합니다. 1개국부터 시작해 단계적으로 확장하는 것도 가능하며, 국가 추가 시 구독 플랜 변경 절차를 통해 진행합니다."},{"category":"서비스 개요","question":"서비스 이용 중 진출 국가를 변경하거나 추가할 수 있나요?","answer":"네, 가능합니다. 매월 정산 마감일(매월 말일) 기준 7영업일 전까지 국가 추가·변경 신청서를 제출하면 다음 구독 주기부터 반영됩니다. 국가 추가 시 해당 국가의 현지화 세팅 기간(약 7~10일)이 별도 소요됩니다."},{"category":"서비스 개요","question":"서비스 이용을 위해 브랜드가 준비해야 할 서류는 무엇인가요?","answer":"사업자등록증 사본, 제품 사진(흰 배경 고해상도 1,000px 이상), 제품 상세 설명(한국어), 수출 가능 여부 확인서(해당 시), 할랄 인증서(말레이시아 진출 시 권장)가 필요합니다. 미국 진출 시에는 FDA 등록 여부도 사전 확인이 필요합니다."},{"category":"서비스 개요","question":"틱톡샵에서 판매 가능한 제품 카테고리에 제한이 있나요?","answer":"틱톡샵 플랫폼 정책상 의약품·의료기기·주류·담배 등은 판매가 불가합니다. K-뷰티(스킨케어·색조·헤어케어), K-푸드(건강식품·스낵류), K-라이프스타일(생활용품·패션잡화) 카테고리가 주요 취급 품목이며, 국가별 규제 품목은 온보딩 미팅 시 사전 확인합니다."},{"category":"서비스 개요","question":"2025년 글로벌 K-뷰티 시장 규모는 얼마이며, 틱톡샵과의 연관성은 무엇인가요?","answer":"2025년 글로벌 K-뷰티 시장 규모는 $14.1B(약 141억 달러)로 예상됩니다. 틱톡샵은 K-뷰티 트렌드를 콘텐츠 소비와 즉각적인 구매로 연결하는 채널로, Medicube의 경우 틱톡샵 누적 조회수 337.8M을 기록하며 매출 직결 효과를 입증했습니다."},{"category":"서비스 개요","question":"Glovek 서비스를 이용하면 브랜드 직접 진출 대비 어떤 비용이 절감되나요?","answer":"직접 진출 시 국가별 법인 설립비(국가당 약 500만~2,000만 원), 현지 CS 인력 채용비(월 200만~400만 원/인), 크리에이터 발굴·계약 비용(건당 50만~500만 원) 등이 발생합니다. Glovek 멀티몰은 이를 월 구독료(49만 원~)로 대체하여 초기 고정비를 최소화합니다."},{"category":"서비스 개요","question":"Glovek 서비스는 어떤 브랜드에게 가장 적합한가요?","answer":"해외 진출 경험이 없거나 초기 단계인 K-뷰티·K-푸드·K-라이프스타일 브랜드에 최적화되어 있습니다. 특히 월 국내 매출 1,000만 원 이상이지만 해외 진출 인프라가 없는 브랜드, 또는 1~2개국 테스트 판매 후 점진적으로 확장하려는 브랜드에게 강력히 추천합니다."},{"category":"서비스 개요","question":"서비스 이용 중 브랜드가 직접 관리해야 하는 업무는 무엇인가요?","answer":"브랜드는 제품 공급(재고 입고)과 제품 기획·개발에 집중하면 됩니다. 현지화 운영, 마케팅 캠페인 기획·실행, 물류·통관, CS 대응, 정산 처리는 Glovek이 전담합니다. 단, 시딩용 샘플 제품 발송 및 재고 보충은 브랜드가 직접 진행합니다."},{"category":"서비스 개요","question":"Glovek 플랫폼 이용권이란 무엇인가요?","answer":"glovek.space 플랫폼 이용과 관련된 내용입니다."},{"category":"서비스 개요","question":"서비스 문의 및 신청은 어떻게 하나요?","answer":"Glovek.space 웹사이트의 ''입점 신청하기'' 버튼을 통해 신청하거나, partners@glovek.space 로 이메일 문의가 가능합니다. 신청 접수 후 영업일 기준 1~2일 이내에 담당 매니저가 연락하여 1:1 온보딩 미팅 일정을 조율합니다."},{"category":"서비스 개요","question":"Glovek 멀티몰 입점과 브랜드 자체 채널 운영의 차이는 무엇인가요?","answer":"멀티몰 입점은 @Glovek 공식 계정 내 입점 방식으로 초기 신뢰도와 트래픽을 즉시 활용할 수 있습니다. 자체 채널은 브랜드 고유 틱톡샵 계정을 운영하는 방식으로 브랜딩 독립성이 높지만 초기 팔로워·신뢰도 구축에 시간이 필요합니다. Glovek은 멀티몰 입점 → 실적 검증 → 자체 채널 독립의 단계적 성장 경로를 지원합니다."},{"category":"서비스 개요","question":"계약 기간 중 서비스를 중도 해지하면 어떻게 되나요?","answer":"월 구독 플랜은 다음 결제일 7일 전까지 해지 신청 시 익월부터 과금이 중단됩니다. 6개월 약정 플랜은 약정 기간 내 해지 시 잔여 기간 구독료의 30%에 해당하는 위약금이 발생합니다. 해지 후 재고는 브랜드 지정 주소로 반송 처리되며, 반송 물류비는 브랜드 부담입니다."},{"category":"구독 플랜 및 요금 구조","question":"구독 플랜의 요금과 판매 수수료를 정리해 주세요.","answer":"Live Focus Track은 월 490,000원 + 판매 수수료 10%이며, Onboarding Track은 별도 협의(가격 문의) + 판매 수수료 10%입니다. 모든 플랜은 VAT 포함가이며, 6개월 약정 시 20% 추가 할인이 적용됩니다."},{"category":"구독 플랜 및 요금 구조","question":"다국가 동시 진행 시 할인은 어떻게 계산되나요?","answer":"1개국은 정가, 2개국은 10% 할인, 3~4개국은 15% 할인, 5개국은 20% 할인이 적용됩니다. 예를 들어 Live Focus Track으로 3개국 진출 시 월 490,000원 × 3개국 × (1 - 15%) = 월 1,249,500원이 됩니다(VAT 포함)."},{"category":"구독 플랜 및 요금 구조","question":"판매 수수료는 어떤 기준으로 부과되나요?","answer":"판매 수수료는 틱톡샵 내 실제 결제 완료된 GMV(Gross Merchandise Value, 총 거래액) 기준으로 부과됩니다. 반품·취소 건은 수수료 산정에서 제외되며, 매월 1일~말일 발생 매출을 기준으로 익월 1~0일에 정산서가 발행됩니다."},{"category":"구독 플랜 및 요금 구조","question":"Live Focus Track 플랜에 포함된 서비스를 구체적으로 설명해 주세요.","answer":"틱톡샵 멀티몰 입점(@Glovek), Glovek 플랫폼 이용권, 벤더 매칭 및 제안(비독점), 제품 상세페이지 현지화 번역, 어필리에이트 캠페인 운영, 물류 대행·발주·CS 업무 대행에 더해, 월 4회 무가 라이브 커머스, 무가 시딩 캠페인 20개 이상, 유가 시딩 캠페인 운영이 포함됩니다(최대 5개 제품 등록)."},{"category":"구독 플랜 및 요금 구조","question":"Live Focus Track이 ''추천'' 플랜으로 표시된 이유는 무엇인가요?","answer":"가격 대비 운영 범위가 가장 균형 잡힌 플랜이기 때문입니다. 기본 입점·번역·어필리에이트 운영에 더해 월 4회 무가 라이브 커머스, 무가 시딩 20개 이상, 유가 시딩 캠페인 운영이 포함되어 초기 국가 파일럿부터 바이럴 확산·매출 전환까지 한 플랜으로 커버할 수 있습니다."},{"category":"구독 플랜 및 요금 구조","question":"Onboarding Track 플랜은 어떤 브랜드에게 적합한가요?","answer":"이미 국내외 매출 실적이 있고, 틱톡샵 내 자체 브랜드 채널(Official Store) 독립을 목표로 하는 브랜드에 적합합니다. 메가 셀럽 캠페인, 대형 GMV 달성 캠페인, 제품 무제한 등록, 브랜드 자체 채널 온보딩 지원이 포함됩니다."},{"category":"구독 플랜 및 요금 구조","question":"6개월 약정과 월 구독의 차이점은 무엇인가요?","answer":"월 구독은 매월 자동 결제되며 언제든 해지 가능(해지 신청 후 익월 중단)합니다. 6개월 약정은 6개월 합계를 일시 결제하는 방식으로, 20% 할인이 적용됩니다. 약정 기간 내 해지 시 잔여 기간 구독료의 30% 위약금이 발생합니다."},{"category":"구독 플랜 및 요금 구조","question":"구독료 결제 방식과 결제일은 어떻게 되나요?","answer":"결제는 신용카드(법인카드 포함) 또는 계좌이체로 가능합니다. 최초 결제일이 구독 시작일이 되며, 이후 매월 동일 일자에 자동 결제됩니다. 계좌이체의 경우 결제 예정일 3영업일 전까지 입금해야 합니다."},{"category":"구독 플랜 및 요금 구조","question":"판매 수수료 정산 주기와 지급 방식은 어떻게 되나요?","answer":"매월 1일~말일 발생한 GMV 기준으로 수수료를 산정하여 익월 1~0일에 정산서를 발행합니다. 브랜드 매출(GMV - 수수료 - 물류비 - 틱톡샵 플랫폼 수수료)은 익월 1~5일에 브랜드 지정 계좌로 원화 입금됩니다."},{"category":"구독 플랜 및 요금 구조","question":"틱톡샵 플랫폼 자체 수수료는 별도로 발생하나요?","answer":"네, 틱톡샵 플랫폼 자체 수수료(국가별 상이, 통상 GMV의 1~5%)가 Glovek 수수료와 별도로 발생합니다. 이 금액은 정산서에 항목별로 투명하게 표기되며, 브랜드 정산 금액 산정 시 차감됩니다."},{"category":"구독 플랜 및 요금 구조","question":"무가 시딩 20개와 유가 시딩의 차이는 구체적으로 무엇인가요?","answer":"무가 시딩은 제품 샘플만 제공하고 크리에이터가 자발적으로 콘텐츠를 제작하는 방식으로, 콘텐츠 품질이나 업로드 시점을 보장하지 않습니다. 유가 시딩은 크리에이터에게 별도 제작비(건당 10만~50만 원 수준)를 지급하여 기획된 콘텐츠를 지정 기간 내 업로드하도록 보장하는 방식입니다."},{"category":"구독 플랜 및 요금 구조","question":"무가 라이브 커머스 월 4회는 어떤 방식으로 진행되나요?","answer":"Glovek 소속 현지 호스트가 브랜드 제품을 소개하는 라이브 방송을 월 4회(회당 약 1~2시간) 진행합니다. 방송 일정은 매월 초 브랜드와 협의하여 확정하며, 방송 전 제품 브리핑 자료(한국어 가능)를 제출하면 현지 언어로 번역하여 진행합니다."},{"category":"구독 플랜 및 요금 구조","question":"제품 등록 수 제한(Live Focus: 5개, Onboarding: 무제한)은 어떻게 적용되나요?","answer":"동시에 스토어에 노출되는 활성 제품 수 기준입니다. 제품 교체는 가능하며, 교체 신청 후 현지화 번역·등록 작업에 약 3~5영업일이 소요됩니다. 제품 교체는 월 1회까지 무료이며, 추가 교체 시 건당 50,000원의 작업비가 발생합니다."},{"category":"구독 플랜 및 요금 구조","question":"GMV 달성 캠페인이란 구체적으로 어떤 서비스인가요?","answer":"Onboarding Track 전용 서비스로, 브랜드와 목표 GMV를 사전 합의한 후 메가 셀럽 섭외, 대형 라이브 커머스, 집중 어필리에이트 캠페인을 통합 운영하는 집중 성장 캠페인입니다. 목표 GMV 미달성 시 다음 달 추가 캠페인을 무상으로 진행합니다."},{"category":"구독 플랜 및 요금 구조","question":"Live Focus Track에서 Onboarding Track으로 업그레이드하려면 어떻게 하나요?","answer":"현재 구독 주기 내 언제든지 업그레이드 신청이 가능합니다. 업그레이드 신청 후 익월 결제일부터 새 플랜이 적용되며, 신청 당월은 기존 플랜 요금이 유지됩니다. 업그레이드 시 추가 현지화 세팅(제품 추가 등록 등)은 약 5~7영업일이 소요됩니다."},{"category":"구독 플랜 및 요금 구조","question":"플랜 다운그레이드도 가능한가요?","answer":"월 구독 플랜의 경우 다음 결제일 1~4일 전까지 다운그레이드 신청 시 익월부터 적용됩니다. 단, 6개월 약정 플랜은 약정 기간 중 다운그레이드가 불가하며, 약정 만료 후 변경 가능합니다."},{"category":"구독 플랜 및 요금 구조","question":"구독료 외에 추가로 발생할 수 있는 비용 항목은 무엇인가요?","answer":"물류비(입고·통관·배송·반품, 별도 청구), 유가 시딩 캠페인 제작비(건당 10만~50만 원), 추가 제품 교체 작업비(건당 50,000원), 틱톡샵 플랫폼 수수료(GMV의 15%), 메가 셀럽 섭외비(Onboarding Track, 별도 협의)가 발생할 수 있습니다."},{"category":"구독 플랜 및 요금 구조","question":"어필리에이트 캠페인 운영에서 크리에이터 커미션은 누가 부담하나요?","answer":"어필리에이트 커미션은 판매 연동 구조로, 크리에이터가 발생시킨 매출의 일정 비율(통상 5~20%, 카테고리·크리에이터 등급별 상이)을 크리에이터에게 지급합니다. 이 커미션은 GMV에서 차감되어 정산되므로 브랜드가 별도로 현금 지출하지 않습니다."},{"category":"구독 플랜 및 요금 구조","question":"벤더 매칭 및 제안(비독점)이란 무엇인가요?","answer":"Glovek이 브랜드 제품에 적합한 현지 유통 벤더(도매상·리셀러)를 발굴하여 연결해 주는 서비스입니다. ''비독점''이란 Glovek이 해당 벤더와의 독점 계약을 요구하지 않으며, 브랜드가 직접 계약·협상할 수 있음을 의미합니다."},{"category":"구독 플랜 및 요금 구조","question":"구독 플랜별 성과 리포트 제공 주기는 어떻게 다른가요?","answer":"Live Focus Track은 격주 리포트(매월 5일·20일 발행), Onboarding Track은 주간 리포트(매주 월요일 발행)가 제공됩니다. 모든 플랜에서 Glovek 대시보드를 통한 실시간 데이터 조회가 가능합니다."},{"category":"셀러 등급 진단 시스템","question":"셀러 등급 진단은 언제, 어떻게 진행되나요?","answer":"등급 진단은 가장 먼저 진행합니다. 브랜드가 플랫폼 신청 단계에서 5대 지표를 자가체크하면 예비 등급이 즉시 산출되며, 이 결과를 1:1 온보딩 미팅 시 참고 자료로 활용하여 최종 등급을 확정합니다."},{"category":"셀러 등급 진단 시스템","question":"셀러 등급 진단의 5대 핵심 지표를 구체적으로 설명해 주세요.","answer":"①글로벌 판매고(아마존·쇼피파이 등 온라인 월 매출 1,000만 원 이상 여부), ②해외 진출 준비(수출 인증·현지 물류 계약 보유 여부), ③해외 판매 경험(직접 수출 이력 6개월 이상 여부), ④오프라인 활동(해외 팝업·전시회 참가 이력 여부), ⑤시딩 진행 경험(인플루언서 콘텐츠 시딩 10회 이상 진행 여부)입니다."},{"category":"셀러 등급 진단 시스템","question":"S등급 판정 기준과 운영 전략을 구체적으로 알려주세요.","answer":"5대 지표 전부 해당하는 브랜드로, 판매 단계에 있습니다. Glovek 멀티몰 입점과 동시에 브랜드 자체 채널(Official Store) 세팅을 병행하며, 메가 셀럽(팔로워 100만 명 이상) 캠페인과 대형 라이브 커머스를 즉시 투입하는 전략을 권장합니다."},{"category":"셀러 등급 진단 시스템","question":"A등급 판정 기준과 운영 전략을 구체적으로 알려주세요.","answer":"5대 지표 중 4개 해당하는 브랜드로, 진출 진행 단계에 있습니다. 자체 채널 세팅은 가능하나 멀티몰을 통한 초기 판매 실적 축적을 병행하며, 메가 캠페인을 통해 3개월 내 스케일업을 목표로 합니다."},{"category":"셀러 등급 진단 시스템","question":"B등급 판정 기준과 운영 전략을 구체적으로 알려주세요.","answer":"5대 지표 중 23개 해당하는 브랜드로, 진출 계획 단계에 있습니다. Glovek 멀티몰 인큐베이팅을 통해 36개월간 시딩 및 초기 판매 실적을 세팅하고, 월 GMV 500만 원 이상 달성 시 A등급으로 재진단하여 스케일업 전략으로 전환합니다."},{"category":"셀러 등급 진단 시스템","question":"C등급 판정 기준과 운영 전략을 구체적으로 알려주세요.","answer":"5대 지표 중 1개 이하 해당하는 브랜드로, 관심 단계에 있습니다. 3~4개월간 멀티몰 입점 운영을 통해 해외 판매 경험과 시딩 경험을 축적하고, 이후 B등급 이상으로 재진단 후 자체 채널 독립 경로로 전환합니다."},{"category":"셀러 등급 진단 시스템","question":"등급은 한 번 정해지면 고정되나요?","answer":"아니요, 매 분기(3개월)마다 재진단이 진행됩니다. 운영 성과(GMV, 콘텐츠 성과, 시딩 경험 축적 등)에 따라 등급이 상향 또는 하향 조정될 수 있으며, 등급 변경 시 운영 전략도 즉시 재설계됩니다."},{"category":"셀러 등급 진단 시스템","question":"등급 진단 결과에 이의가 있을 경우 어떻게 하나요?","answer":"진단 결과 수령 후 5영업일 이내에 이의신청서를 제출하면 재진단을 진행합니다. 재진단은 Glovek 운영팀 리더급 담당자가 직접 진행하며, 재진단 결과는 최종 확정됩니다."},{"category":"셀러 등급 진단 시스템","question":"S등급 브랜드도 Glovek 멀티몰을 이용해야 하나요?","answer":"S등급 브랜드는 자체 채널 직접 세팅이 가능하지만, Glovek 멀티몰을 통한 초기 트래픽 활용과 2만 명 크리에이터 네트워크 연계를 위해 멀티몰 입점을 병행하는 것을 권장합니다. Onboarding Track 이용 시 자체 채널 온보딩을 동시에 지원합니다."},{"category":"셀러 등급 진단 시스템","question":"해외 판매 경험이 전혀 없는 신규 브랜드는 어떤 등급을 받게 되나요?","answer":"통상 C등급을 받게 됩니다. 단, 국내 온라인 매출이 월 3,000만 원 이상이거나 오프라인 팝업 경험이 있는 경우 B등급으로 진단될 수 있습니다. C등급이라도 Live Focus Track으로 즉시 입점 가능합니다."},{"category":"셀러 등급 진단 시스템","question":"등급 진단 비용이 별도로 발생하나요?","answer":"아니요, 등급 진단은 모든 구독 플랜에 무료로 포함되어 있습니다. 분기별 재진단도 무료로 진행됩니다."},{"category":"셀러 등급 진단 시스템","question":"등급별로 추천 구독 플랜이 다른가요?","answer":"네, C·B등급은 Live Focus Track, A등급은 Live Focus Track 또는 Onboarding Track, S등급은 Onboarding Track이 권장됩니다. 단, 예산 및 목표에 따라 브랜드가 자유롭게 플랜을 선택할 수 있습니다."},{"category":"셀러 등급 진단 시스템","question":"온보딩 미팅은 대면으로만 진행되나요?","answer":"아니요, 대면 또는 화상 미팅(Zoom·Google Meet) 모두 가능합니다. 미팅 시간은 약 60~90분이며, 브랜드 목표, 제품 라인업, 진출 국가, 예산 등을 종합적으로 점검합니다."},{"category":"셀러 등급 진단 시스템","question":"온보딩 완료 후 담당 매니저가 배정되나요?","answer":"네, 온보딩 완료 후 전담 어카운트 매니저(AM) 1명이 배정됩니다. AM은 주간 또는 격주 정기 리포트 공유, 캠페인 기획 협의, 이슈 대응 등을 담당하며, 카카오톡 채널 또는 이메일로 연락 가능합니다."},{"category":"셀러 등급 진단 시스템","question":"온보딩 중 제품 상세페이지 번역은 몇 개 언어로 제공되나요?","answer":"진출 국가에 따라 영어(미국), 베트남어, 태국어, 말레이어, 영어(싱가포르) 등 최대 5개 언어로 번역됩니다. 번역은 현지 네이티브 번역가가 진행하며, 브랜드 검토 후 최종 등록됩니다."},{"category":"현지화 운영 및 국가별 전략","question":"현지화 스토어 운영에서 ''프로모션 최적화''는 구체적으로 어떤 활동인가요?","answer":"틱톡샵 자체 프로모션 도구를 활용하여 신규 고객 첫 구매 할인(통상 10~15% 쿠폰), 무료배송(Freeship) 이벤트, 플래시 세일(특정 시간대 30~50% 할인), 번들 할인(2개 구매 시 추가 10% 할인) 등을 기획·운영합니다."},{"category":"현지화 운영 및 국가별 전략","question":"미국 틱톡샵 진출 시 특별히 준비해야 할 사항이 있나요?","answer":"FDA 등록 여부 확인(화장품의 경우 OTC 의약품 성분 포함 시 필수), 영문 라벨링(성분표·용량·제조사 정보), 미국 현지 반품 주소 확보가 필요합니다. Glovek은 FDA 등록 절차 가이드 및 영문 라벨링 검토를 온보딩 미팅 시 지원합니다."},{"category":"현지화 운영 및 국가별 전략","question":"베트남 시장에서 K-뷰티 제품의 경쟁력은 무엇인가요?","answer":"베트남은 틱톡샵 침투율 1위 국가로, 가성비 스킨케어(앰플·세럼·선크림)와 메이크업(쿠션·립틴트)에 대한 수요가 높습니다. K-뷰티 브랜드는 현지 브랜드 대비 품질 신뢰도가 높아 프리미엄 포지셔닝이 가능하며, 틱톡 라이브 커머스를 통한 실시간 구매 전환율이 동남아 최고 수준입니다."},{"category":"현지화 운영 및 국가별 전략","question":"태국 시장에서 라이브 커머스가 강세인 이유는 무엇인가요?","answer":"태국 소비자는 제품 사용 방법과 실제 효과를 직접 확인하고 구매하는 성향이 강합니다. 특히 색조 화장품(파운데이션·아이섀도)과 선케어 제품은 라이브 방송에서 현지 호스트가 직접 발색·테스트하는 콘텐츠가 높은 전환율을 기록합니다."},{"category":"현지화 운영 및 국가별 전략","question":"말레이시아 진출 시 할랄 인증이 없으면 판매가 불가한가요?","answer":"할랄 인증이 없어도 판매는 가능하나, 말레이시아 무슬림 소비자(전체 인구의 약 60%)를 타겟으로 하는 경우 할랄 인증이 사실상 필수입니다. 할랄 인증 없이도 비무슬림 소비자를 대상으로 스킨케어·헤어케어 제품 판매가 가능하며, Glovek은 할랄 인증 취득 절차 가이드를 별도 제공합니다."},{"category":"현지화 운영 및 국가별 전략","question":"싱가포르 시장에서 이너뷰티 카테고리가 강세인 이유는 무엇인가요?","answer":"싱가포르는 1인당 GDP가 높고 건강·웰니스에 대한 관심이 높은 소비자층이 두텁습니다. 콜라겐 드링크, 글루타치온 보충제, 비타민 C 앰플 등 이너뷰티 제품에 대한 수요가 꾸준히 증가하고 있으며, 프리미엄 K-뷰티 브랜드에 대한 신뢰도가 높습니다."},{"category":"현지화 운영 및 국가별 전략","question":"국가별로 상품명과 상세페이지가 모두 다르게 등록되나요?","answer":"네, 각 국가의 언어와 소비자 선호에 맞게 별도로 현지화됩니다. 예를 들어 동일 제품이라도 미국에서는 영문 성분 강조형, 베트남에서는 가성비·효과 중심, 싱가포르에서는 프리미엄 포지셔닝 중심으로 상세페이지가 각각 작성됩니다."},{"category":"현지화 운영 및 국가별 전략","question":"현지 CS(고객 서비스) 응대는 어떤 언어로, 어떤 채널을 통해 이루어지나요?","answer":"각 국가 현지어(영어·베트남어·태국어·말레이어)로 응대하며, 틱톡샵 내 메시지 채널과 이메일을 통해 처리됩니다. CS 응대 시간은 현지 시간 기준 평일 오전 9시~오후 6시이며, 평균 응답 시간은 4시간 이내를 목표로 합니다."},{"category":"현지화 운영 및 국가별 전략","question":"반품 처리 기준과 절차는 어떻게 되나요?","answer":"틱톡샵 플랫폼 정책에 따라 수령 후 7일 이내 미개봉 제품에 한해 반품이 가능합니다. 고객이 반품 신청 시 Glovek CS팀이 현지어로 응대하고, 현지 물류센터에서 반품 수거 후 상태 확인을 거쳐 환불 처리합니다. 반품 물류비는 제품 하자의 경우 브랜드 부담, 단순 변심의 경우 고객 부담입니다."},{"category":"현지화 운영 및 국가별 전략","question":"스토어 내 베스트셀러 및 신상품 큐레이션은 어떻게 관리되나요?","answer":"Glovek 운영팀이 주간 단위로 판매 데이터를 분석하여 베스트셀러 섹션과 신상품 섹션을 업데이트합니다. 특정 제품을 베스트셀러 상단에 노출하고 싶은 경우 브랜드가 사전 요청할 수 있으며, 프로모션 연계 시 노출 우선순위를 높일 수 있습니다."},{"category":"현지화 운영 및 국가별 전략","question":"틱톡샵 내 광고(유료 광고)도 Glovek이 운영해 주나요?","answer":"유료 광고(틱톡 Ads) 운영은 기본 구독 플랜에 포함되지 않습니다. 별도 광고비 예산을 브랜드가 제공할 경우 Glovek이 광고 세팅·운영을 대행할 수 있으며, 광고 운영 대행 수수료는 광고비의 15%입니다."},{"category":"현지화 운영 및 국가별 전략","question":"현지화 번역의 품질은 어떻게 보장되나요?","answer":"현지 네이티브 번역가가 1차 번역 후 현지 마케터가 2차 검수하는 2단계 품질 관리 프로세스를 거칩니다. 번역 완료 후 브랜드에 최종 확인을 요청하며, 수정 요청은 최초 번역 완료 후 5영업일 이내에 1회 무료로 반영됩니다."},{"category":"현지화 운영 및 국가별 전략","question":"각 국가의 틱톡샵 플랫폼 수수료는 얼마인가요?","answer":"국가별로 상이하며, 미국 약 25%, 베트남 약 13%, 태국 약 24%, 말레이시아 약 13%, 싱가포르 약 2~4% 수준입니다(틱톡샵 정책에 따라 변동 가능). 정확한 수수료는 온보딩 미팅 시 최신 정책 기준으로 안내됩니다."},{"category":"현지화 운영 및 국가별 전략","question":"국가별 배송 소요 기간은 어떻게 되나요?","answer":"현지 물류센터에 재고가 있는 경우 미국 2~5영업일, 베트남 1~3영업일, 태국 1~3영업일, 말레이시아 2~4영업일, 싱가포르 1~2영업일이 소요됩니다. 재고 소진 후 한국에서 직배송하는 경우 국가별로 7~14영업일이 추가 소요됩니다."},{"category":"현지화 운영 및 국가별 전략","question":"재고 보충은 어떻게 진행되나요?","answer":"Glovek 대시보드에서 국가별 재고 현황을 실시간으로 확인할 수 있습니다. 재고가 설정 임계치(기본값: 30개) 이하로 떨어지면 자동 알림이 발송되며, 브랜드는 알림 수신 후 5영업일 이내에 재고를 발송해야 합니다. 재고 발송 주소는 Glovek 지정 국내 물류 집하장입니다."},{"category":"현지화 운영 및 국가별 전략","question":"현지 물류센터는 어느 국가에 위치해 있나요?","answer":"미국(LA 또는 뉴저지), 베트남(호치민), 태국(방콕), 말레이시아(쿠알라룸푸르), 싱가포르(싱가포르 시내) 각 1개소에 Glovek 제휴 물류센터가 운영됩니다."},{"category":"현지화 운영 및 국가별 전략","question":"통관 시 발생하는 관세는 누가 부담하나요?","answer":"수입 관세 및 부가세는 현지 소비자 가격에 반영되어 구매자가 부담하는 구조입니다. 단, 국가별 면세 한도(예: 미국 $800 이하 소액 수입 면세) 적용 여부에 따라 달라질 수 있으며, 통관 과정에서 발생하는 행정 처리 비용은 물류비에 포함됩니다."},{"category":"현지화 운영 및 국가별 전략","question":"제품 가격은 국가별로 다르게 설정할 수 있나요?","answer":"네, 국가별로 현지 시장 가격, 경쟁사 가격, 관세·물류비를 반영하여 브랜드가 직접 판매가를 설정할 수 있습니다. Glovek은 국가별 적정 가격 설정을 위한 시장 분석 자료를 온보딩 미팅 시 제공합니다."},{"category":"현지화 운영 및 국가별 전략","question":"틱톡샵 내 제품 리뷰 관리는 어떻게 이루어지나요?","answer":"Glovek CS팀이 부정적 리뷰에 대해 현지어로 신속하게 응대하고, 문제 해결 내용을 공개 댓글로 남겨 브랜드 신뢰도를 관리합니다. 긍정적 리뷰 유도를 위해 구매 후 7일 시점에 리뷰 요청 메시지를 자동 발송합니다."},{"category":"현지화 운영 및 국가별 전략","question":"틱톡샵 내 제품 노출 순위를 높이기 위한 전략은 무엇인가요?","answer":"판매량·전환율·리뷰 수·콘텐츠 조회수 등이 틱톡샵 알고리즘 노출 순위에 영향을 미칩니다. Glovek은 초기 시딩 캠페인으로 콘텐츠 조회수를 빠르게 확보하고, 프로모션 쿠폰으로 전환율을 높이며, 라이브 커머스로 실시간 판매량을 끌어올리는 통합 전략을 실행합니다."},{"category":"물류 및 정산","question":"Glovek 구독 계약 시 물류는 어떻게 처리되나요?","answer":"Glovek 구독 계약을 체결하면 물류 파트너사인 **디노(DINO)**와의 물류 서비스 계약이 자동으로 연동됩니다. 별도의 물류사 계약 절차 없이 Glovek 온보딩 완료 시점부터 디노의 국내 집하·해외 배송·현지 라스트마일·반품 서비스를 즉시 이용할 수 있습니다."},{"category":"물류 및 정산","question":"디노(DINO)와의 물류 계약이 자동 연동된다는 것은 구체적으로 어떤 의미인가요?","answer":"브랜드가 Glovek 구독 계약서에 서명하면 디노 물류 이용 동의가 포함되어 있어 별도 계약서 작성 없이 디노 서비스를 이용할 수 있습니다. 물류비 청구도 Glovek을 통해 통합 청구되므로 브랜드는 디노와 직접 정산할 필요가 없습니다."},{"category":"물류 및 정산","question":"디노(DINO) 물류 서비스의 주요 기능은 무엇인가요?","answer":"국내 집하(브랜드 → 디노 국내 센터), 해외 발송(국내 → 현지 물류센터), 현지 라스트마일 배송(현지 물류센터 → 소비자), 반품 수거 및 처리, 통관 대행, 실시간 배송 추적 서비스가 포함됩니다."},{"category":"물류 및 정산","question":"물류비는 어떻게 산정되나요?","answer":"물류비는 제품 무게·부피·목적지 국가·배송 방식(일반/특급)에 따라 달라집니다. 기본 단가는 디노 표준 요율표 기준이며, Glovek 구독 고객은 일반 단가 대비 약 10~15% 할인된 협약 단가가 적용됩니다. 정확한 물류비는 온보딩 미팅 시 제품 정보(무게·사이즈)를 기반으로 견적을 제공합니다."},{"category":"물류 및 정산","question":"물류비 청구 및 정산 주기는 어떻게 되나요?","answer":"물류비는 매월 1일~말일 발생한 실비 기준으로 익월 1~0일에 청구서가 발행됩니다. 물류비는 브랜드 정산 금액에서 차감하거나, 잔액이 부족한 경우 별도 청구서로 발행됩니다. 결제 기한은 청구서 발행 후 7영업일 이내입니다."},{"category":"물류 및 정산","question":"재고를 국내에서 해외 물류센터로 보내는 절차는 어떻게 되나요?","answer":"①브랜드가 Glovek 대시보드에서 입고 신청서 작성 → ②디노 국내 집하장 주소로 제품 발송(택배 또는 화물) → ③디노가 수량 검수 후 해외 발송 → ④현지 물류센터 입고 완료 시 대시보드에 재고 반영. 국내 발송부터 현지 입고 완료까지 통상 5~10영업일이 소요됩니다."},{"category":"물류 및 정산","question":"재고 분실 또는 파손 시 어떻게 처리되나요?","answer":"디노 물류 과정에서 발생한 분실·파손은 디노 보험 정책에 따라 제품 원가 기준으로 보상됩니다. 보상 한도는 건당 최대 100만 원이며, 고가 제품의 경우 별도 화물 보험 가입을 권장합니다. 보상 신청은 분실·파손 확인 후 5영업일 이내에 Glovek 담당 매니저를 통해 접수합니다."},{"category":"물류 및 정산","question":"매출 정산은 어떤 통화로, 언제 지급되나요?","answer":"5개국에서 발생한 외화 매출(USD·VND·THB·MYR·SGD)은 Glovek이 정산 기준일(매월 말일) 환율로 원화 환산하여 익월 1~5일에 브랜드 지정 원화 계좌로 입금됩니다. 환율은 하나은행 고시 매매기준율을 적용합니다."},{"category":"물류 및 정산","question":"정산서에는 어떤 항목이 포함되나요?","answer":"국가별 총 GMV, 반품·취소 차감액, 틱톡샵 플랫폼 수수료, Glovek 판매 수수료, 어필리에이트 커미션 차감액, 물류비, 기타 비용(유가 캠페인비 등), 최종 지급액(원화)이 항목별로 명시됩니다."},{"category":"물류 및 정산","question":"정산 금액에 이의가 있을 경우 어떻게 하나요?","answer":"정산서 수령 후 5영업일 이내에 Glovek 정산팀(partners@glovek.space)으로 이의신청서를 제출하면 됩니다. Glovek은 접수 후 7영업일 이내에 검토 결과를 회신하며, 오류가 확인된 경우 다음 정산 주기에 차액을 정산합니다."},{"category":"물류 및 정산","question":"브랜드 매출이 발생하지 않은 달에도 구독료를 내야 하나요?","answer":"네, 구독료는 매출 발생 여부와 무관하게 매월 고정 청구됩니다. 단, 판매 수수료는 실제 GMV 발생 시에만 부과됩니다."},{"category":"물류 및 정산","question":"통관 서류 준비는 브랜드가 직접 해야 하나요?","answer":"아니요, Glovek 및 디노가 통관에 필요한 서류(인보이스·패킹리스트·원산지증명서 등) 작성을 대행합니다. 브랜드는 제품 정보(HS코드·원가·성분)를 최초 입고 시 1회 제공하면 이후 반복 발송 시 자동 처리됩니다."},{"category":"물류 및 정산","question":"환율 변동으로 인한 손실은 누가 부담하나요?","answer":"환율 변동 리스크는 Glovek이 관리합니다. 정산 기준일(매월 말일) 환율을 적용하여 원화 정산하므로, 브랜드는 환율 변동에 따른 별도 손익을 부담하지 않습니다. 단, 급격한 환율 변동(±10% 이상) 발생 시 별도 협의를 통해 정산 기준을 조정할 수 있습니다."},{"category":"물류 및 정산","question":"국가별 세금(VAT·GST 등) 처리는 어떻게 되나요?","answer":"각 국가의 소비세(미국 Sales Tax, 베트남 VAT 10%, 태국 VAT 7%, 말레이시아 SST 6%, 싱가포르 GST 9%)는 틱톡샵 플랫폼이 자동 징수하여 납부합니다. 브랜드는 별도로 현지 세금 신고 의무가 없으며, 정산서에 세금 차감 내역이 명시됩니다."},{"category":"물류 및 정산","question":"물류 추적은 실시간으로 가능한가요?","answer":"네, Glovek 대시보드에서 국가별·주문별 배송 상태(집하·발송·통관·배송중·배송완료)를 실시간으로 확인할 수 있습니다. 소비자에게도 틱톡샵 앱 내에서 자동으로 배송 추적 링크가 제공됩니다."},{"category":"마케팅 및 성과 리포트","question":"어필리에이트 크리에이터는 어떤 기준으로 선정되나요?","answer":"팔로워 수(나노: 1만~10만, 마이크로: 10만~100만, 메가: 100만 이상), 카테고리 적합성(뷰티·푸드·라이프스타일 등), 최근 3개월 평균 조회수, 어필리에이트 판매 전환율 이력을 종합 평가하여 선정합니다. Live Focus Track은 나노~마이크로 크리에이터 중심, Onboarding Track은 메가 크리에이터까지 활용합니다."},{"category":"마케팅 및 성과 리포트","question":"시딩 캠페인 진행 후 콘텐츠 성과는 어떻게 측정되나요?","answer":"콘텐츠 조회수, 좋아요·댓글·공유 수, 제품 클릭수, 틱톡샵 장바구니 추가 수, 최종 구매 전환수 및 전환율을 측정합니다. 이 데이터는 Glovek 대시보드에서 캠페인별로 확인 가능하며, 성과 리포트에 포함됩니다."},{"category":"마케팅 및 성과 리포트","question":"라이브 커머스 1회당 평균 매출은 어느 정도 기대할 수 있나요?","answer":"제품 카테고리·가격대·크리에이터 팔로워 수에 따라 크게 다르지만, 초기 브랜드의 경우 회당 평균 50만~200만 원, 인지도가 쌓인 이후에는 회당 500만~2,000만 원 이상의 매출을 기대할 수 있습니다. 태국·베트남 시장에서 라이브 커머스 전환율이 특히 높습니다."},{"category":"마케팅 및 성과 리포트","question":"어필리에이트 캠페인의 ROAS는 어느 정도 기대할 수 있나요?","answer":"카테고리별로 상이하나, K-뷰티 기준 어필리에이트 캠페인 평균 ROAS는 3~8배 수준입니다. 초기 3개월은 브랜드 인지도 구축 단계로 ROAS가 낮을 수 있으며, 6개월 이상 운영 시 안정적인 ROAS 확보가 가능합니다."},{"category":"마케팅 및 성과 리포트","question":"성과 리포트에 포함되는 KPI 항목은 구체적으로 무엇인가요?","answer":"국가별 GMV(총 거래액), 주문 건수, 평균 주문 단가, 전환율, 콘텐츠 조회수, 어필리에이트 캠페인 ROAS, 라이브 커머스 시청자 수·구매 전환율, 시딩 콘텐츠 수·조회수, 재구매율, CS 문의 건수·처리율이 포함됩니다."},{"category":"마케팅 및 성과 리포트","question":"성과 리포트를 기반으로 어떤 액션 제안을 받을 수 있나요?","answer":"전환율이 낮은 국가에 대한 프로모션 강화 제안, 조회수 대비 전환율이 높은 크리에이터 추가 투입 제안, 재구매율이 높은 제품의 번들 구성 제안, 신규 진출 추천 국가 및 카테고리 제안, 다음 달 캠페인 소재 방향 제안 등이 포함됩니다."},{"category":"마케팅 및 성과 리포트","question":"크리에이터가 제작한 콘텐츠의 저작권은 누구에게 있나요?","answer":"무가 시딩 콘텐츠의 저작권은 크리에이터에게 있으며, 브랜드는 해당 콘텐츠를 자사 채널에 무단 재게시할 수 없습니다. 유가 시딩 계약 시 콘텐츠 재사용권(6개월 또는 1년)을 포함하는 계약을 체결할 수 있으며, 재사용권 포함 시 추가 비용이 발생합니다."},{"category":"마케팅 및 성과 리포트","question":"인플루언서 시딩 후 제품이 부정적으로 리뷰되는 경우 어떻게 대응하나요?","answer":"Glovek은 시딩 전 크리에이터에게 제품 브리핑을 충분히 제공하여 부정적 리뷰 발생을 최소화합니다. 부정적 콘텐츠가 게시된 경우 해당 크리에이터와 협의하여 수정 또는 삭제를 요청하며, 브랜드에 즉시 보고합니다. 단, 크리에이터의 자발적 의견 표현을 강제로 삭제할 수는 없습니다."},{"category":"마케팅 및 성과 리포트","question":"메가 셀럽 캠페인은 어떻게 진행되나요?","answer":"Onboarding Track 전용으로, 팔로워 100만 명 이상의 현지 메가 인플루언서와 협업하는 캠페인입니다. 브랜드 제품 소개 전용 콘텐츠 12편 제작, 라이브 커머스 공동 진행, 어필리에이트 링크 고정 노출 등이 포함됩니다. 메가 셀럽 섭외비는 별도 협의(통상 건당 500만~3,000만 원)이며, 캠페인 기획부터 완료까지 약 3~4주가 소요됩니다."},{"category":"마케팅 및 성과 리포트","question":"국가별 채널 성과를 비교 분석할 수 있나요?","answer":"네, Glovek 대시보드에서 국가별·채널별(시딩·라이브·어필리에이트) 성과를 분리하여 비교 분석할 수 있습니다. 예를 들어 베트남에서는 시딩 채널이, 태국에서는 라이브 커머스 채널이 더 높은 전환율을 보이는 경우 채널 전략을 국가별로 최적화합니다."},{"category":"마케팅 및 성과 리포트","question":"캠페인 성과가 기대에 미치지 못할 경우 어떻게 대응하나요?","answer":"성과 미달 시 Glovek 담당 매니저가 원인 분석 리포트를 제공하고, 크리에이터 교체·소재 변경·프로모션 강화 등 개선 액션을 즉시 실행합니다. Live Focus Track 이상 플랜에서는 성과 미달 월에 추가 시딩 5개를 무상으로 진행합니다."},{"category":"마케팅 및 성과 리포트","question":"틱톡샵 알고리즘 변화에 따른 대응은 어떻게 이루어지나요?","answer":"Glovek은 틱톡샵 공식 파트너로서 플랫폼 정책 변경 정보를 사전에 공유받습니다. 알고리즘 변화 감지 시 즉시 운영 전략을 조정하며, 브랜드에 변경 사항과 대응 방안을 공지합니다."},{"category":"마케팅 및 성과 리포트","question":"브랜드가 직접 크리에이터에게 연락하거나 별도 계약을 맺을 수 있나요?","answer":"Glovek 서비스 이용 중에는 Glovek이 매칭한 크리에이터와 브랜드가 직접 계약하는 것을 제한합니다. 서비스 종료 후에는 크리에이터 정보를 별도 협의를 통해 공유받을 수 있습니다."},{"category":"마케팅 및 성과 리포트","question":"브랜드 자체 채널 독립 후에도 Glovek 서비스를 계속 이용할 수 있나요?","answer":"네, 자체 채널 독립 후에도 Glovek의 크리에이터 네트워크·캠페인 운영·물류·정산 서비스를 별도 계약을 통해 계속 이용할 수 있습니다. 자체 채널 운영 전용 플랜은 별도 협의를 통해 맞춤 제공됩니다."},{"category":"마케팅 및 성과 리포트","question":"Glovek 서비스를 통해 실제로 달성 가능한 목표 GMV는 어느 정도인가요?","answer":"브랜드 인지도·제품 경쟁력·투입 예산에 따라 크게 다르나, Live Focus Track 기준 3개월 후 월 GMV 100만~500만 원, 6개월 후 월 GMV 500만~3,000만 원, Onboarding Track 기준 6개월 후 월 GMV 3,000만 원 이상을 목표로 운영 전략을 설계합니다. 이는 참고용 수치이며 실제 성과는 보장되지 않습니다."},{"category":"온보딩·입점 심화 안내","question":"온보딩 트랙의 서비스는 Glovek 틱톡 멀티몰 안에서 진행되나요?","answer":"네. Glovek이 운영하는 공식 틱톡샵 멀티몰(@Glovek) 안에서 입점·판매가 진행되며, Onboarding Track은 이후 브랜드 자체 채널 독립까지 지원합니다."},{"category":"온보딩·입점 심화 안내","question":"Glovek 플랫폼 이용권에는 어떤 서비스가 포함되며, 금액과 이용 기간은 어떻게 되나요?","answer":"Glovek 플랫폼 이용권은 입점 구독에 포함된 혜택으로 별도 구매 항목이 아닙니다. 콘텐츠 레퍼런스 검색, 인플루언서 검색·성과 조회, 인플루언서 제안(컨택) 기능을 구독 기간 동안 이용하실 수 있습니다."},{"category":"온보딩·입점 심화 안내","question":"제품 상세페이지 현지화 번역은 미국 기준 초월 번역인가요? 원본 파일 공유와 자체 샵 사용(라이선스)이 가능한가요?","answer":"현지화 번역은 미국 시장 기준의 초월 번역 수준으로 제공되며, 규제·민감 표현은 배제합니다. 최종 사용 전 브랜드가 반드시 검수·확정하며, 완성된 번역 원본은 공유되어 향후 브랜드 자체 샵 운영에도 그대로 사용하실 수 있습니다."},{"category":"온보딩·입점 심화 안내","question":"인플루언서 어필리에이트 커미션은 구독료에 포함인가요, 매출에서 별도 차감인가요?","answer":"어필리에이트 커미션은 구독료와 별도이며, 실제 발생한 매출(GMV)에서 차감·정산됩니다. 제품·인플루언서·카테고리에 따라 요율이 달라질 수 있고, 브랜드가 별도로 현금을 선지출하지 않습니다."},{"category":"온보딩·입점 심화 안내","question":"제품 등록이 무제한인데, 30개 이상 등록 시 소요 시간과 등록 대행 여부는 어떻게 되나요?","answer":"공식 멀티몰 기반 등록은 수량 제한이 없으며, 브랜드가 제품 정보를 전달해 주시면 Glovek이 등록을 대행합니다. 다만 월 30건 이상 대량 등록은 일정 조율을 위해 담당 매니저와 별도 협의로 진행합니다."},{"category":"온보딩·입점 심화 안내","question":"GMV 달성 캠페인의 목표는 어떻게 설정되고, 어떤 방식으로 운영되나요?","answer":"브랜드 상황(제품·목표 매출·마케팅 예산)에 맞춰 사전 제안서를 드리고, 양사 합의 후 진행합니다. 어필리에이트·시딩·라이브 커머스·유료 광고를 목표에 맞게 조합해 운영합니다."},{"category":"온보딩·입점 심화 안내","question":"구독 종료 후 제품 노출 기간, 구독 재개 시 재노출, 미판매 재고 반환·물류비 부담은 어떻게 되나요?","answer":"구독 종료 시 마지막 결제 주기(결제일+30일)까지 노출이 유지되며, 이후 미판매 재고는 반환됩니다. 반환·물류 비용은 브랜드 부담이라 초기 대량 입고보다 담당 매니저 가이드에 따른 적정 수량 입고를 권장합니다. 구독을 재개하면 다시 노출할 수 있습니다."},{"category":"온보딩·입점 심화 안내","question":"물류비와 유가(유료) 캠페인의 비용 구조 자료를 공유해 주실 수 있나요?","answer":"물류비는 제품 사양·목적지에 따른 개별 단가표로 안내드리며 단가표에서 확인하실 수 있습니다. 유가 캠페인은 브랜드 예산에 맞춰 참여자 리스트·광고안을 담은 제안서를 드린 후 협의해 확정합니다."},{"category":"온보딩·입점 심화 안내","question":"무가 라이브 커머스 1회당 참여 제품 수와 평균 매출은 어느 정도인가요?","answer":"무가 라이브는 1회당 기본 1개 SKU로 구성되며, 세트 구성이 필요하면 담당자가 라이브 팀과 조율해 제안드립니다. 회당 매출은 국가·참여자·제품에 따라 편차가 커 실제 데이터는 1:1 미팅에서 사례 기준으로 안내드립니다."},{"category":"온보딩·입점 심화 안내","question":"무가 시딩 인플루언서의 평균 규모, 제품·인플루언서 선택 가능 여부, 제품 제공 방식은 어떻게 되나요?","answer":"무가 시딩은 배포 규모에 따라 3단계 레벨로 운영됩니다. 인플루언서는 브랜드 USP 기준으로 사전 선별해 제공하며, 목표 진행 인원의 약 1.5배수 내에서 선정합니다. 시딩 제품은 브랜드 제공분을 현지 물류로 배포하며, 조회수 등은 인플루언서·콘텐츠별 편차가 커 단일 수치 안내가 어려운 점 양해 부탁드립니다."},{"category":"온보딩·입점 심화 안내","question":"자체 채널(미국 틱톡샵) 온보딩 60~75일 완료가 보장되나요? 지연·거절 시 처리 방안은 있나요?","answer":"사전에 온보딩 가능 조건(등급 A~S)을 진단한 뒤 진행하며, 충분 조건을 갖춘 경우 통상 60~75일 내 완료를 목표로 합니다. 일부 지연이 발생할 수 있으며, 이 경우 기간을 연장해 마무리되도록 지원합니다."},{"category":"온보딩·입점 심화 안내","question":"자체 채널 온보딩 시 샵 오픈 대행 외에 추가로 제공되는 서비스는 무엇인가요?","answer":"샵 오픈 대행 외에도 물류 가이드, 인증 가이드, 현지 CS 및 계정 연동 등 운영 대행이 포함됩니다."},{"category":"온보딩·입점 심화 안내","question":"멀티몰 입점 구독을 제외하고, 자체 채널 온보딩만 지원하는 단품 프로그램이 있나요?","answer":"현재는 멀티몰 입점 구독과 분리된 ''자체 채널 온보딩 단품'' 프로그램은 제공하지 않습니다."}]'::jsonb)
  AS x(category text, question text, answer text)
WHERE NOT EXISTS (SELECT 1 FROM qna_entries q WHERE q.question = x.question);
